    local horizons = (solo and not mustGo) and { 0.2, 0.45, 0.75, 1.1, 1.6, 2.4 } or { 0.2, 0.45, 0.75, 1.1 }
    local dScale = mustGo and 0.5 or 1
    local function wT(T) return math.max(0.3, 1.25 - T * 0.5) * (T < 0.5 and 1 or dScale) end
    if not inStart then H.leftStart = true end
    local function zoneScale(p) return (not H.leftStart and H.inZone(sz, Vector3.new(p.X, r.Position.Y, p.Z), 0)) and 0.15 or 1 end
    local function costOf(dir)
        if dir == Vector3.zero and dodge then
            local cost = 60 + (inStart and 300 or 0)
            for _, T in ipairs(horizons) do cost = cost + danger(me, T) * wT(T) end
            return cost
        end
        if dir == Vector3.zero then
            local cost = ((inStart and waitOk and (nearD < 55 or (#cats >= 6 and left > 16)) and not mustGo) and 4 or (inStart and 250 or 60)) + urgency * 40 + (mustGo and 5000 or 0) + ((H.leftStart and not inStart) and 400 or 0)
            for _, T in ipairs(horizons) do cost = cost + danger(me, T) * (inStart and 0.15 or wT(T)) end
            return cost
        end
        local cost = -dir:Dot(fwd) * (dodge and math.clamp(distC / 40, 0, 1.5) * 25 or (10 + urgency * 20))
        if H.leftStart and not inStart and not dodge then cost = cost + math.max(0, -dir:Dot(fwdGoal) - 0.1) * (distLeft < 70 and 1200 or 400) end
        if openDir then cost = cost - dir:Dot(openDir) * 150 end
        local hitD = H.blockedDist(origin, dir, 34 * 2.4)
        if hitD and hitD < 3 then return 1e7 end
        cost = cost + math.max(0, 14 - (hitD or 99)) * (threat and 12 or 4)
        local stuck = false
        for _, T in ipairs(horizons) do
            local travel = 34 * rS * T
            if hitD and hitD < travel then
                if not stuck then cost = cost + (T < 0.5 and 400 or 120) stuck = true end
                travel = math.max(0, hitD - 1.5)
            end
            local p = me + dir * travel
            local zp = dodge and Vector3.new(p.X, r.Position.Y, p.Z)
            cost = cost + (danger(p, T) * (dodge and 1 or zoneScale(p)) + edgeCost(p) + ((dodge and (H.inZone(gz, zp, 0) or H.inZone(sz, zp, 0))) and 40000 or 0)) * wT(T)
        end
        return cost
    end
    local best, bc
    local curCost
    for k, dir in ipairs(cands) do
        local cost = costOf(dir)
        if k == 3 and H.curDir then curCost = cost end
        if not bc or cost < bc then best, bc = dir, cost end
    end
    local wasWaiting = H.waiting
    if H.curDir and curCost and best ~= Vector3.zero and curCost <= bc + math.max(15, math.abs(bc) * 0.08) then best, bc = H.curDir, curCost end
    if best == Vector3.zero and not wasWaiting and H.curDir and curCost and curCost <= bc + 20 then best = H.curDir end
    H.waiting = best == Vector3.zero
    local now = os.clock()
    local dt = math.clamp(now - (H.lastT or now), 0, 0.1)
    H.lastT = now
    local gd = H.gemT and (H.gemT - me).Magnitude
    if gd and gd < 10 then
        H.gemNearSince = H.gemNearSince or os.clock()
        if os.clock() - H.gemNearSince > 1.1 then H.gemBan[gkey(H.gemT)] = true; H.gemLock = nil; H.gemT = nil; H.gemNearSince = nil; gd = nil end
    else
        H.gemNearSince = nil
    end
    if gd and gd > 3 and (H.gemT - me).Unit:Dot(H.curDir or fwdGoal) < 0.2 then H.gemBan[gkey(H.gemT)] = true; H.gemLock = nil; H.gemT = nil; gd = nil end
    local nearGem = gd and gd < 12 and gd > 3 and not threat and danger(H.gemT, gd / 34) < 60
    if nearGem then best = (H.gemT - me).Unit end
    local jnow = os.clock()
    if threat and H.jukeDir and jnow < (H.jukeUntil or 0) then
        local jc = costOf(H.jukeDir)
        if jc <= bc + 400 then best, bc = H.jukeDir, jc end
    end
    if threat and best ~= Vector3.zero and jnow >= (H.jukeUntil or 0) and H.curDir and best:Dot(H.curDir) < 0.5 then
        H.jukeDir, H.jukeUntil = best, jnow + 0.4
    end
    if not threat then H.jukeDir = nil end
    if best ~= Vector3.zero then
        local prev = H.curDir or best
        local turn = (bc > 900 or threat) and 30 or (nearGem and 11 or 9)
        local mix = prev:Lerp(best, math.min(1, dt * turn))
        H.curDir = mix.Magnitude > 0.05 and mix.Unit or best
    else
        H.curDir = nil
    end
    best = H.curDir or Vector3.zero
    if dodge and best ~= Vector3.zero then
        local function nearZone(d)
            local q = me + d * 10
            local qp = Vector3.new(q.X, r.Position.Y, q.Z)
            return H.inZone(gz, qp, -3) or H.inZone(sz, qp, -3)
        end
        if nearZone(best) then
            local alt, ac
            for _, d in ipairs(cands) do
                if d ~= Vector3.zero and not nearZone(d) then
                    local cst = costOf(d)
                    if not ac or cst < ac then alt, ac = d, cst end
                end
            end
            best = alt or Vector3.zero
            H.curDir = alt
            H.gemLock, H.gemT = nil, nil
        end
    end
    S.task = dodge and (threat and "Dodging" or "Holding the field") or best == Vector3.zero and "Waiting for a gap" or (mustGo and "Going for it" or (H.gemT and "Grabbing a gem" or "Crossing"))
    H.dashWhy = not on("rn_dash") and "off" or (best == Vector3.zero and "still") or (not c:GetAttribute("DashReady") and "notready") or ((os.clock() - H.lastDash <= 1.15) and "cd") or "ok"
    if on("rn_dash") and best ~= Vector3.zero and c:GetAttribute("DashReady") and os.clock() - H.lastDash > 1.15 then
        local nearC, nearD
        for _, cc in ipairs(cats) do local d = (flat(cc.r.Position) - me).Magnitude if not nearD or d < nearD then nearC, nearD = cc, d end end
        if nearC then
            local rel = flat(nearC.r.Position) - me
            local closing = (H.vel(nearC.r) - flat(r.AssemblyLinearVelocity)):Dot(-rel.Unit)
            local hd = H.blockedDist(origin, best, 12)
            if hd then H.dashWhy = "blocked" .. math.floor(hd) end
            local dived = nearC.dive or (nearC.r.Parent and nearC.r.Parent:GetAttribute("TackleActive") == true)
            local finish = distLeft < 30 and nearD < 24 and not dodge
            if not hd and ((nearD < reach + math.max(0, closing) * 0.4 and nearD < reach + 9) or (dived and nearD < 22) or (nearD < 15 and closing > -4) or finish) then
                H.lastDash = os.clock(); S.dashes = S.dashes + 1
                H.dash()
            end
        end
    end
    H.face = best ~= Vector3.zero and best or nil
    if os.clock() - (H.dlogT or 0) > 0.1 then
        H.dlogT = os.clock()
        H.dlog = H.dlog or {}
        local cs = {}
        table.sort(cats, function(a, b) return (a.p - me).Magnitude < (b.p - me).Magnitude end)
        for i = 1, math.min(3, #cats) do local cc = cats[i] cs[i] = string.format("%s %.0f@%.0f,%.0f v%.0f,%.0f", cc.name:sub(1, 6), (cc.p - me).Magnitude, cc.p.X, cc.p.Z, cc.v.X, cc.v.Z) end
        table.insert(H.dlog, string.format("%.2f me %.0f,%.0f dir %.2f,%.2f fwd %.2f,%.2f bc %.0f dash=%s %s%s%s%s | %s", Workspace:GetServerTimeNow(), me.X, me.Z, best.X, best.Z, fwd.X, fwd.Z, bc or 0, tostring(H.dashWhy), threat and ("THREAT " .. math.floor(threatD) .. " ") or "", H.gemT and "GEM " or "", mustGo and "MUSTGO " or "", solo and "SOLO" or "", table.concat(cs, " ; ")))
        if #H.dlog > 80 then table.remove(H.dlog, 1) end
    end
    return best
end

function H.catcher(c, r)
    H.trackAll()
    local me = flat(r.Position)
    local runners = H.players("Runner", true)
    local best, bt
    for _, t in ipairs(runners) do
        local p, v = flat(t.r.Position), H.vel(t.r)
        local tt = 0
        for _ = 1, 3 do tt = math.min(1.5, (p + v * tt - me).Magnitude / 37) end
        if not bt or tt < bt then best, bt = { t = t, aim = p + v * tt, p = p, v = v }, tt end
    end
    if not best then S.task = "No runners"; return Vector3.zero end
    S.task = "Chasing " .. best.t.name
    local want = best.aim - me
    if want.Magnitude < 0.5 then return Vector3.zero end
    local wantU = want.Unit
    local origin = r.Position - Vector3.new(0, 0.5, 0)
    local dir = wantU
    if H.blockedDist(origin, wantU, math.min(want.Magnitude, 20)) then
        local goal3 = Vector3.new(best.aim.X, r.Position.Y, best.aim.Z)
        local pd = H.pathDir(r.Position, goal3)
        local bd, bs
        for i = 0, 23 do
            local d = Vector3.new(math.cos(i * math.pi / 12), 0, math.sin(i * math.pi / 12))
            local hit = H.blockedDist(origin, d, 12)
            local sc = d:Dot(pd) * 2 + d:Dot(wantU) - (hit and 5 or 0)
            if not bs or sc > bs then bd, bs = d, sc end
        end
        dir = bd
    end
    local lead = best.p + best.v * 0.22
    local dLead = (lead - me).Magnitude
    H.tgtD = dLead
    local dr = c:GetAttribute("DashReady")
    if on("ct_dash") and dr ~= false and dLead > 11 and dLead < 24 and os.clock() - H.lastDash > 1.15 and not H.blockedDist(origin, (lead - me).Unit, 14) then
        H.lastDash = os.clock()
        S.dashes = (S.dashes or 0) + 1
        H.dash()
    end
    if on("ct_tackle") and dLead <= 7 and dLead > 0.5 then
        r.CFrame = CFrame.lookAt(r.Position, r.Position + (lead - me).Unit)
        if H.tackle() then S.tackles = (S.tackles or 0) + 1 end
    end
    local ext = on("ct_reach") and math.clamp(val("ct_reach_n", 5), 0, 6) or 0
    local tNow = flat(best.t.r.Position)
    local dNow = (tNow - me).Magnitude
    if (dLead <= val("ct_range", 9) or (ext > 0 and dNow <= val("ct_range", 9) + ext)) and os.clock() - H.lastSwing > 0.86 then
        H.lastSwing = os.clock()
        local look = (dLead <= val("ct_range", 9)) and (lead - me) or (tNow - me)
        if look.Magnitude > 0.1 then
            local shift = math.clamp(dNow - val("ct_range", 9) + 2, 0, ext)
            r.CFrame = CFrame.lookAt(r.Position, r.Position + look.Unit)
            MeleeEvent:FireServer({ id = HttpService:GenerateGUID(false), at = Workspace:GetServerTimeNow(), direction = look.Unit, position = r.Position + look.Unit * shift })
            S.swings = S.swings + 1
        end
    end
    local fl = lead - me
    H.face = fl.Magnitude > 0.5 and fl.Unit or dir
    return dir
end

