            H.dlog = nil; H.goal = nil; H.finishing = nil; H.curDir = nil; H.gemLock = nil; H.gemBan = nil; H.waiting = nil; H.leftStart = nil; H.threat = nil; H.tgtD = nil; H.imminent = nil; H.entryX = nil
