local ESP = { hl = {}, gem = {} }
function ESP.clear(tbl) for k, v in pairs(tbl) do pcall(function() v:Destroy() end); tbl[k] = nil end end
function ESP.step()
    local wantC, wantR = on("es_catch"), on("es_run")
    for _, pl in ipairs(Players:GetPlayers()) do
        if pl ~= lp then
            local role = pl:GetAttribute("GameRole")
            local show = (role == "Catcher" and wantC) or (role == "Runner" and wantR and pl:GetAttribute("RunState") == "Active")
            local ch = pl.Character
            local h = ESP.hl[pl]
            if show and ch then
                if not h or h.Parent ~= ch then
                    if h then pcall(function() h:Destroy() end) end
                    h = Instance.new("Highlight")
                    h.Name = "CW_ESP"
                    h.FillTransparency = 0.6
                    h.OutlineTransparency = 0
                    h.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
                    h.Parent = ch
                    ESP.hl[pl] = h
                end
                local col = role == "Catcher" and Color3.fromRGB(255, 70, 70) or Color3.fromRGB(80, 230, 120)
                h.FillColor, h.OutlineColor = col, col
            elseif h then
                pcall(function() h:Destroy() end); ESP.hl[pl] = nil
            end
        end
    end
    for pl, h in pairs(ESP.hl) do if not pl.Parent then pcall(function() h:Destroy() end); ESP.hl[pl] = nil end end
    local lg = Workspace:FindFirstChild("LocalRunnerGems")
    if on("es_gems") and lg then
        for _, g in ipairs(lg:GetChildren()) do
            if not ESP.gem[g] then
                local hl = Instance.new("Highlight")
                hl.FillColor = Color3.fromRGB(90, 200, 255); hl.OutlineColor = hl.FillColor
                hl.FillTransparency = 0.4; hl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
                hl.Parent = g
                ESP.gem[g] = hl
            end
        end
        for g, hl in pairs(ESP.gem) do if not g.Parent then pcall(function() hl:Destroy() end); ESP.gem[g] = nil end end
    else
        ESP.clear(ESP.gem)
    end
end
task.spawn(function()
    while RUNNING do pcall(ESP.step); task.wait(0.5) end
end)
onClean(function() ESP.clear(ESP.hl); ESP.clear(ESP.gem) end)

