do
    local key = "CW_HV_CamFollow"
    local yaw
    RunService:BindToRenderStep(key, Enum.RenderPriority.Last.Value, function(dt)
        if not (RUNNING and on("cam_follow")) or H.mv.Magnitude < 0.1 then yaw = nil return end
        local cam = Workspace.CurrentCamera
        local r = hrp()
        if not (cam and r) then return end
        local cf = cam.CFrame
        local focus = r.Position + Vector3.new(0, 2, 0)
        local dist = (cf.Position - focus).Magnitude
        local pitch = math.asin(math.clamp(cf.LookVector.Y, -0.9, 0.9))
        local want = math.atan2(-H.mv.X, -H.mv.Z)
        yaw = yaw or math.atan2(-cf.LookVector.X, -cf.LookVector.Z)
        local dw = (want - yaw + math.pi) % (2 * math.pi) - math.pi
        yaw = yaw + dw * math.min(1, (dt or 0.016) * 6)
        local rot = CFrame.Angles(0, yaw, 0) * CFrame.Angles(pitch, 0, 0)
        if dist < 1.5 then cam.CFrame = CFrame.new(cf.Position) * rot else cam.CFrame = CFrame.new(focus) * rot * CFrame.new(0, 0, dist) end
    end)
    onClean(function() pcall(function() RunService:UnbindFromRenderStep(key) end) end)
end

