H.lockConns = {}
function H.findLock()
    if not getconnections then return end
    H.lockConns = {}
    for _, cn in ipairs(getconnections(RunService.PreSimulation)) do
        local f = cn.Function
        local ok, src = pcall(debug.info, f, "s")
        if ok and type(src) == "string" and src:find("LockedCameraClient") then H.lockConns[#H.lockConns + 1] = cn end
    end
end
H.lockOff = false
function H.setLock(off)
    if H.lockOff == off then return end
    H.lockOff = off
    if #H.lockConns == 0 then H.findLock() end
    for _, cn in ipairs(H.lockConns) do pcall(function() if off then cn:Disable() else cn:Enable() end end) end
end
onClean(function() H.setLock(false) end)
track(RunService.PreSimulation:Connect(function()
    local want = RUNNING and on("bot_face") and H.face ~= nil and lp:GetAttribute("RunState") == "Active"
    H.setLock(want and true or false)
    if not want then return end
    local c, r, h = char(), hrp(), hum()
    if not (c and r and h) or h.Health <= 0 or r.Anchored or h.Sit or h.PlatformStand then return end
    if c:GetAttribute("TackleActive") or c:GetAttribute("GearMotion") or c:GetAttribute("MovementLocked") then return end
    if lp:GetAttribute("RunState") ~= "Active" then return end
    local f = Vector3.new(H.face.X, 0, H.face.Z)
    if f.Magnitude < 0.1 then return end
    f = f.Unit
    local cur = Vector3.new(r.CFrame.LookVector.X, 0, r.CFrame.LookVector.Z)
    cur = cur.Magnitude > 0.1 and cur.Unit or f
    local now = os.clock()
    local dt = math.clamp(now - (H.faceT or now), 0, 0.05)
    H.faceT = now
    local ca, ta = math.atan2(cur.X, cur.Z), math.atan2(f.X, f.Z)
    local d = (ta - ca + math.pi) % (2 * math.pi) - math.pi
    local maxStep = 10 * math.max(dt, 1 / 120)
    local na = ca + math.clamp(d, -maxStep, maxStep)
    r.CFrame = CFrame.lookAt(r.Position, r.Position + Vector3.new(math.sin(na), 0, math.cos(na)))
end))

