local repo = "https://raw.githubusercontent.com/deividcomsono/Obsidian/main/"
local function fetch(u)
    for _ = 1, 6 do
        local ok, s = pcall(function() return game:HttpGet(u) end)
        if ok and type(s) == "string" and #s > 100 then return s end
        local rq = request or http_request or (syn and syn.request)
        if rq then
            local ok2, res = pcall(rq, { Url = u, Method = "GET" })
            if ok2 and type(res) == "table" and type(res.Body) == "string" and #res.Body > 100 then return res.Body end
        end
        task.wait(2)
    end
    error("could not download " .. u)
end
