local EM = { list = {}, map = {} }
pcall(function()
    local cat = require(CoH:FindFirstChild("Emotes", true):FindFirstChild("EmoteCatalog"))
    local function scan(t, depth)
        if depth > 3 then return end
        for _, v in pairs(t) do
            if type(v) == "table" then
                if type(v.Id) == "string" and v.Animation then
                    local n = tostring(v.Name or v.Id)
                    if not EM.map[n] then EM.map[n] = v; EM.list[#EM.list + 1] = n end
                else
                    scan(v, depth + 1)
                end
            end
        end
    end
    scan(cat, 0)
    table.sort(EM.list)
end)
function EM.stop()
    if EM.track then pcall(function() EM.track:Stop(0.2) EM.track:Destroy() end) EM.track = nil end
    if EM.snd then pcall(function() EM.snd:Destroy() end) EM.snd = nil end
end
function EM.play(name)
    EM.stop()
    local e = EM.map[name]
    local h, r = hum(), hrp()
    local an = h and h:FindFirstChildOfClass("Animator")
    if not (e and an) then return end
    local a = Instance.new("Animation")
    a.AnimationId = "rbxassetid://" .. (tostring(e.Animation):gsub("%D", ""))
    EM.track = an:LoadAnimation(a)
    EM.track.Priority = Enum.AnimationPriority.Action
    EM.track.Looped = true
    EM.track:Play(0.2)
    if e.Sound and r then
        local s = Instance.new("Sound")
        s.SoundId = "rbxassetid://" .. (tostring(e.Sound):gsub("%D", ""))
        s.Volume, s.Looped = 0.6, true
        s.Parent = r
        s:Play()
        EM.snd = s
    end
end
track(RunService.Heartbeat:Connect(function()
    if EM.track then
        local h = hum()
        if not h or h.MoveDirection.Magnitude > 0.1 then EM.stop() end
    end
end))
onClean(EM.stop)

do
    local GameAction = CoH.Game:FindFirstChild("GameAction")
    track(Session:GetAttributeChangedSignal("Phase"):Connect(function()
        local ph = Session:GetAttribute("Phase")
        if not (RUNNING and GameAction) then return end
        if ph == "HeroChoice" then
            task.delay(1.2, function()
                local ch = val("vt_choice", "Off")
                if ch ~= "Off" and Session:GetAttribute("SelectedUserId") == lp.UserId then pcall(function() GameAction:FireServer("HeroChoice", ch) end) end
            end)
        elseif ph == "SelectHero" then
            task.delay(1.2, function()
                if not on("vt_pick") or Session:GetAttribute("LeadUserId") ~= lp.UserId then return end
                local pool = {}
                for _, p in ipairs(Players:GetPlayers()) do if p ~= lp and p:GetAttribute("GameRole") == "Runner" then pool[#pool + 1] = p end end
                if #pool > 0 then local p = pool[math.random(#pool)]; pcall(function() GameAction:FireServer("SelectHero", p.UserId) end) end
            end)
        end
    end))
end

